func handleEvent(ctx context.Context, ev Event) error {
    if seen, _ := cache.Exists(ctx, "processed:"+ev.EventID); seen {
        return nil
    }
    if err := chargeCustomer(ctx, ev); err != nil {
        return err
    }
    cache.Set(ctx, "processed:"+ev.EventID, true, 24*time.Hour)
    return nil
}
